import { describe, expect, test } from 'bun:test'

import type { Indicator, KLineData } from 'klinecharts'

import ssl from '../ssl'
import { seedWarmup } from './bandpassj'
import fixture from './fixtures/wscan_parity.json'
import nnfx from './index'
import { triggerFrom } from './iscalc'
import { tcfOptions, trendContinuationFactor } from './tcf'
import { vossWarmup } from './voss'
import { asRatio } from './vppoc'

// The indicators of the windicators NNFX scan's top systems, against windicators' own output --
// the code the scan ran (fixtures/wscan_parity.json, generated by
// notes/research/NoNonSenseForex/tests/gen_nnfx_wscan_parity.py from the windicators snapshot
// 9f7b6c8). SSL is not an NNFX-directory template, but system 3's C1 is it (at length 7, HMA).

const bars: KLineData[] = fixture.bars.ts.map((timestamp, i) => ({
  timestamp,
  open: fixture.bars.open[i] as number,
  high: fixture.bars.high[i] as number,
  low: fixture.bars.low[i] as number,
  close: fixture.bars.close[i] as number,
  volume: fixture.bars.volume[i] as number
}))

type Row = Record<string, number | undefined>
const templates = new Map([...nnfx, ssl].map((t) => [t.name, t]))
function run(name: string, calcParams: number[], data: KLineData[] = bars): Row[] {
  const t = templates.get(name)
  if (t === undefined) throw new Error(name)
  return (t.calc as (d: KLineData[], i: Indicator) => Row[])(data, { calcParams } as unknown as Indicator)
}
function defaults(name: string): number[] {
  const t = templates.get(name)
  if (t === undefined) throw new Error(name)
  return [...(t.calcParams as number[])]
}

// Each template's calcParams in order, by the names the fixture's `chart` uses; a template's
// trailing settings the fixture does not name keep their defaults.
const PARAM_ORDER: Record<string, string[]> = {
  HWMA: ['na', 'nb', 'nc'],
  HWC: ['scalar', 'na', 'nb', 'nc', 'nd'],
  HWC_PCT: ['scalar', 'na', 'nb', 'nc', 'nd', 'ma'],
  TCF: ['n', 't3', 'b', 'count'],
  VWMACD: ['fast', 'slow', 'signal', 'sma'],
  MACDEXT: ['fast', 'slow', 'signal', 'ma'],
  BANDPASS_J: ['period', 'bandwidth'],
  BANDPASS_J_RAW: ['period', 'bandwidth'],
  IS_CALC: ['period', 'nbchandelier', 'lag'],
  KALMAN: ['q', 'r', 'horizon'],
  KST: ['roc1', 'roc2', 'roc3', 'roc4', 'sma1', 'sma2', 'sma3', 'sma4', 'signal', 'ma'],
  SSL: ['length', 'ma'],
  TURTLE: ['trade', 'stop'],
  PTL: ['slow', 'fast'],
  VOSS: ['period', 'predict', 'bandwidth'],
  VP_POC: ['period', 'value_area', 'tick']
}

function params(template: string, chart: Record<string, number>): number[] {
  const p = defaults(template)
  PARAM_ORDER[template].forEach((k, i) => {
    p[i] = chart[k]
  })
  return p
}

// The 250 fixture bars are all inside the band-pass and Voss templates' warm-ups (bandpassj.ts,
// voss.ts), so parity is checked with them off; the warm-ups themselves are tested below.
const WARMUP_AT: Record<string, number> = { BANDPASS_J: 2, BANDPASS_J_RAW: 3, VOSS: 4 }

function near(actual: number | undefined, expected: number): boolean {
  return actual !== undefined && Math.abs(actual - expected) <= 1e-9 * Math.max(1, Math.abs(expected))
}

describe('parity with windicators, the code the windicators NNFX scan ran', () => {
  test('the fixture is the generated one, and covers every template', () => {
    expect(fixture.$comment).toContain('gen_nnfx_wscan_parity.py')
    expect(new Set(fixture.cases.map((c) => c.template))).toEqual(new Set(Object.keys(PARAM_ORDER)))
  })

  test("each template's defaults are a system's setting the fixture checks", () => {
    for (const name of Object.keys(PARAM_ORDER)) {
      const checked = fixture.cases
        .filter((c) => c.template === name)
        .map((c) => params(name, c.chart as unknown as Record<string, number>))
      expect(checked).toContainEqual(defaults(name))
    }
  })

  for (const c of fixture.cases) {
    const p = params(c.template, c.chart as unknown as Record<string, number>)
    if (c.template in WARMUP_AT) p[WARMUP_AT[c.template]] = 0
    // A case may carry its own bars: TCF's tie case and the Turtle and PTL tie cases (rounded
    // prices), and the volume profile's zero, missing (null in the JSON) and unit volumes.
    const own = c as { high?: number[]; low?: number[]; close?: number[]; volume?: Array<number | null> }
    const data = bars.map((b, i) => ({
      ...b,
      high: own.high === undefined ? b.high : own.high[i],
      low: own.low === undefined ? b.low : own.low[i],
      close: own.close === undefined ? b.close : own.close[i],
      volume: own.volume === undefined ? b.volume : (own.volume[i] ?? Number.NaN)
    }))
    test(`${c.template}(${p.join(', ')}) -- ${c.source}`, () => {
      const rows = run(c.template, p, data)
      const out = c.out as unknown as Record<string, Array<number | null>>
      // IS Calculation's trigger is blank while the EMPTY_VALUE seed left in it is above 1e-12 (iscalc.ts).
      const chart = c.chart as unknown as Record<string, number>
      const blankUntil = c.template === 'IS_CALC' ? triggerFrom(chart.nbchandelier, chart.period + chart.lag) : 0
      for (const [key, expected] of Object.entries(out)) {
        const bad: Array<{ i: number; actual: number | undefined; expected: number | null }> = []
        expected.forEach((e, i) => {
          const a = rows[i][key]
          const blank = e === null || (key === 'trigger' && i < blankUntil)
          if (blank ? a !== undefined : !near(a, e)) bad.push({ i, actual: a, expected: e })
        })
        expect({ key, bad: bad.slice(0, 5) }).toEqual({ key, bad: [] })
        expect(expected.filter((v) => v !== null).length).toBeGreaterThan(bars.length / 2)
      }
    })
  }
})

describe('the readings the systems trade on', () => {
  const sides: Array<[string, string]> = [['HWMA', 'hwma'], ['HWC', 'middle'], ['KALMAN', 'mean']]
  for (const [name, key] of sides) {
    test(`${name}: the side is the close's against the line, and takes both`, () => {
      const rows = run(name, defaults(name))
      rows.forEach((r, i) => {
        const line = r[key]
        if (line !== undefined) expect(r.side).toBe(Math.sign(bars[i].close - line))
      })
      expect(new Set(rows.map((r) => r.side).filter((s) => s !== undefined && s !== 0))).toEqual(new Set([1, -1]))
    })
  }

  const overlays: Array<[string, string, number]> = [['TURTLE', 'line', 2], ['PTL', 'slow', 2]]
  for (const [name, key, invertAt] of overlays) {
    test(`${name}: the state is the close against the ${key} line, flipped by "inverted"`, () => {
      for (const inverted of [0, 1]) {
        const p = defaults(name)
        p[invertAt] = inverted
        const dir = inverted === 1 ? -1 : 1
        const rows = run(name, p)
        rows.forEach((r, i) => {
          const line = r[key]
          if (line !== undefined) expect(r.state).toBe(dir * Math.sign(bars[i].close - line))
        })
        expect(new Set(rows.map((r) => r.state).filter((s) => s !== undefined))).toEqual(new Set([1, -1]))
      }
    })
  }

  test("TURTLE: nothing before bar 2, where the source's first pass starts, whatever the closes do", () => {
    const rise: KLineData[] = [1, 2, 3, 4].map((x, i) => ({ timestamp: i, open: x, high: x, low: x, close: x + 0.5, volume: 1 }))
    const rows = run('TURTLE', defaults('TURTLE'), rise)
    expect(rows.slice(0, 2)).toEqual([{}, {}])
    expect(rows[2].trend).toBe(1)
  })

  test('TURTLE: a close equal to the channel high or low is not a breakout, as in the source', () => {
    const bar = (i: number, high: number, low: number, close: number): KLineData => ({ timestamp: i, open: close, high, low, close, volume: 1 })
    const flat = Array.from({ length: 12 }, (_, i) => bar(i, 1.2, 1.0, 1.1))
    // Short on a close below the 10-bar low, then a close exactly at the 10-bar high: still short.
    const down = run('TURTLE', [10, 5, 1], [...flat, bar(12, 1.1, 0.9, 0.95), bar(13, 1.2, 1.0, 1.2)])
    expect([down[12].trend, down[13].trend]).toEqual([-1, -1])
    // Long on a close above the 10-bar high, then a close exactly at the 10-bar low: still long.
    const up = run('TURTLE', [10, 5, 1], [...flat, bar(12, 1.3, 1.1, 1.25), bar(13, 1.2, 1.0, 1.0)])
    expect([up[12].trend, up[13].trend]).toEqual([1, 1])
  })

  test("TURTLE: the close is above the line exactly while the channel is long, so inverted is the channel's trend reversed", () => {
    const rows = run('TURTLE', defaults('TURTLE'))
    for (const r of rows) if (r.trend !== undefined) expect(r.state).toBe(-r.trend)
  })

  const crosses: Array<[string, string, number]> = [['HWC_PCT', 'percent', 6], ['MACDEXT', 'signal', 4], ['KST', 'signal', 10]]
  for (const [name, key, invertAt] of crosses) {
    test(`${name}: the state is the ${key} line against its average, flipped by "inverted"`, () => {
      for (const inverted of [0, 1]) {
        const p = defaults(name)
        p[invertAt] = inverted
        const rows = run(name, p)
        const dir = inverted === 1 ? -1 : 1
        rows.forEach((r) => {
          const line = r[key]
          if (line !== undefined && r.ma !== undefined) expect(r.state).toBe(dir * Math.sign(line - r.ma))
          else expect(r.state).toBeUndefined()
        })
        expect(new Set(rows.map((r) => r.state).filter((s) => s !== undefined))).toEqual(new Set([1, -1]))
      }
    })
  }

  const zeros: Array<[string, string, number]> = [
    ['TCF', 'plus', 4],
    ['VWMACD', 'signal', 4],
    ['BANDPASS_J_RAW', 'bp', 2],
    ['IS_CALC', 'slope', 3],
    ['VOSS', 'filt', 3]
  ]
  for (const [name, key, invertAt] of zeros) {
    test(`${name}: the state is the ${key} line against zero, flipped by "inverted"`, () => {
      for (const inverted of [0, 1]) {
        const p = defaults(name)
        p[invertAt] = inverted
        if (name in WARMUP_AT) p[WARMUP_AT[name]] = 0
        const dir = inverted === 1 ? -1 : 1
        const rows = run(name, p)
        for (const r of rows) {
          const line = r[key]
          if (line !== undefined) expect(r.state).toBe(dir * Math.sign(line))
        }
        expect(rows.filter((r) => r[key] !== undefined).length).toBeGreaterThan(bars.length / 2)
      }
    })
  }

  test("IS_CALC: the trigger is blank exactly while the source's EMPTY_VALUE seed is above 1e-12", () => {
    const rows = run('IS_CALC', defaults('IS_CALC'))
    const from = triggerFrom(22, 5)
    expect(from).toBeGreaterThan(22 + 100)
    rows.forEach((r, i) => {
      if (i < from) expect(r.trigger).toBeUndefined()
      else expect(Math.abs(r.trigger as number)).toBeLessThan(1)
    })
  })

  test('BANDPASS_J_RAW: the raw line is BANDPASS_J\'s bp', () => {
    const raw = run('BANDPASS_J_RAW', [30, 0.1206, 1, 0])
    const signal = run('BANDPASS_J', [30, 0.1206, 0])
    raw.forEach((r, i) => {
      expect(r.bp).toBe(signal[i].bp as number)
    })
  })

  // The seed's decay at the systems' settings, as measured on the prod pairs (bandpassj.ts), and
  // a history long enough to leave the warm-up: a deterministic random walk.
  const long: KLineData[] = (() => {
    let x = 1.1
    let seed = 7
    return Array.from({ length: 2000 }, (_, i) => {
      seed = (seed * 1103515245 + 12345) % 2147483648
      x *= 1 + (seed / 2147483648 - 0.5) * 0.01
      return { timestamp: i * 86400000, open: x, high: x * 1.002, low: x * 0.998, close: x, volume: 1 }
    })
  })()

  test('BANDPASS_J / BANDPASS_J_RAW: blank until the seed is below 1e-4, then the line drawn from the first bar', () => {
    expect(seedWarmup(30, 0.1206)).toBe(1459)
    expect(seedWarmup(36, 0.2412)).toBe(876)
    for (const name of ['BANDPASS_J', 'BANDPASS_J_RAW']) {
      const at = WARMUP_AT[name]
      const on = run(name, defaults(name), long)
      const p = defaults(name)
      p[at] = 0
      const off = run(name, p, long)
      const warm = seedWarmup(p[0], p[1])
      expect(defaults(name)[at]).toBe(1)
      on.forEach((r, i) => {
        if (i < warm) expect(r).toEqual({})
        else expect(r).toEqual(off[i])
      })
      expect(off[warm - 1].bp).toBeDefined()
    }
  })

  test('VOSS: blank until the start-up error is below 1e-4, then the line drawn from the first bar', () => {
    expect(vossWarmup(36, 2, 0.1675)).toBe(668)
    const on = run('VOSS', defaults('VOSS'), long)
    const p = defaults('VOSS')
    p[4] = 0
    const off = run('VOSS', p, long)
    expect(defaults('VOSS')[4]).toBe(1)
    on.forEach((r, i) => {
      if (i < 668) expect(r).toEqual({})
      else expect(r).toEqual(off[i])
    })
    expect(off[667].filt).toBeDefined()
  })

  test('VP_POC: the exit reads the profile low against the value area low, so inverted it closes shorts only', () => {
    // At the default tick (0.055) EURUSD's three closes almost always share a bin; on a JPY-like
    // price (x 100) they often do not.
    const jpy = bars.map((b) => ({ ...b, open: b.open * 100, high: b.high * 100, low: b.low * 100, close: b.close * 100 }))
    for (const inverted of [0, 1]) {
      const p = defaults('VP_POC')
      p[3] = inverted
      const rows = run('VP_POC', p, jpy)
      for (const r of rows) {
        if (r.profile_low === undefined) continue
        expect(r.value_area_low as number).toBeGreaterThanOrEqual(r.profile_low)
        expect(r.state).toBe((inverted === 1 ? -1 : 1) * Math.sign(r.profile_low - (r.value_area_low as number)))
      }
      expect(new Set(rows.map((r) => r.state).filter((s) => s !== undefined))).toEqual(new Set([0, inverted === 1 ? 1 : -1]))
    }
  })

  test('VP_POC: the tick and the value area are read as the decimals they print, as windicators reads them', () => {
    expect(asRatio(0.055)).toEqual([11, 200])
    expect(asRatio(0.63)).toEqual([63, 100])
    expect(asRatio(0.05)).toEqual([1, 20])
    expect(asRatio(1)).toEqual([1, 1])
    expect(asRatio(0)).toEqual([0, 1])
    expect(asRatio(1e-8)).toEqual([1, 100000000])
    expect(asRatio(2.5e-7)).toEqual([1, 4000000])
  })

  test('BANDPASS_J: the signal is +1 while the normalised line is below the trigger', () => {
    const rows = run('BANDPASS_J', [30, 0.1206, 0])
    for (const r of rows) {
      if (r.norm === undefined || r.trigger === undefined) continue
      expect(r.signal).toBe(r.norm < r.trigger ? 1 : r.norm > r.trigger ? -1 : 0)
    }
  })

  test("the scan's tested readings are the defaults: everything inverted but KST", () => {
    expect(defaults('TURTLE')[2]).toBe(1)
    expect(defaults('PTL')[2]).toBe(1)
    expect(defaults('VOSS')[3]).toBe(1)
    expect(defaults('VP_POC')[3]).toBe(1)
    expect(defaults('HWC_PCT')[6]).toBe(1)
    expect(defaults('MACDEXT')[4]).toBe(1)
    expect(defaults('TCF')[4]).toBe(1)
    expect(defaults('VWMACD')[4]).toBe(1)
    expect(defaults('BANDPASS_J_RAW')[2]).toBe(1)
    expect(defaults('IS_CALC')[3]).toBe(1)
    expect(defaults('KST')[10]).toBe(0)
  })

  test("HWC's middle line is the HWMA at the same level, velocity and acceleration weights", () => {
    const hwc = run('HWC', [1.5, 0.3, 0.067, 0.15, 0.1])
    const hwma = run('HWMA', [0.3, 0.067, 0.15])
    hwc.forEach((r, i) => {
      expect(r.middle).toBe(hwma[i].hwma as number)
    })
  })

  test("TCF: one pass equals the source's per-bar restart wherever the restart is invisible", () => {
    // 3,000 closes: the fixture's, repeated with a drift so no stretch recurs exactly.
    const close: number[] = []
    for (let k = 0; close.length < 3000; k++) for (const b of bars) close.push(b.close * (1 + 0.01 * k) + 0.0001 * Math.sin(close.length))
    for (const params of [[15, 10, 1.0815, 500], [20, 5, 0.618, 400]]) {
      const o = tcfOptions(params)
      const fast = trendContinuationFactor(close, o)
      const exact = trendContinuationFactor(close, o, true)
      for (const key of ['plus', 'minus'] as const) {
        const worst = Math.max(...fast[key].map((v, i) => Math.abs(v - exact[key][i])))
        expect(worst).toBeLessThan(1e-12)
      }
    }
    // Where it is visible (a short window), the restart is kept: fast and exact are one path.
    const o = tcfOptions([15, 10, 1.0815, 60])
    expect(trendContinuationFactor(close, o)).toEqual(trendContinuationFactor(close, o, true))
  })

  test('TCF: the recalculation window only matters once the history is longer than it', () => {
    // Below `count` bars every bar comes from one pass over the whole history, whatever `count` is.
    const short = bars.slice(0, 90)
    expect(run('TCF', [15, 10, 1.0815, 100, 1], short)).toEqual(run('TCF', [15, 10, 1.0815, 500, 1], short))
    expect(run('TCF', [15, 10, 1.0815, 100, 1])).not.toEqual(run('TCF', [15, 10, 1.0815, 500, 1]))
  })
})
